填写下面程序的整行输出（三个整数以空格隔开）。引用参数 longest 会在函数内赋值。
```cpp
#include <iostream>
#include <string>
using namespace std;
string compact(const string& s, char skip) {
    string t;
    for (char c : s) {
        if (c != skip) t.push_back(c);
    }
    return t;
}
int groups(const string& s, int& longest) {
    int count = 0;
    int run = 0;
    longest = 0;
    for (int i = 0; i < static_cast<int>(s.size()); ++i) {
        if (i == 0 || s[i] != s[i - 1]) {
            ++count;
            run = 1;
        } else {
            ++run;
        }
        if (run > longest) longest = run;
    }
    return count;
}
int main() {
    string t = compact("a#abb##aa#b", '#');
    int best;
    int n = groups(t, best);
    cout << n << " " << best << " " << t.size();
}
```

